// Parity: the device rule for "which city am I in" must give the same answer as atlas.regions.closest in Python
// for every case in tests/js/regions_golden.json (generated by scripts/make_regions_golden.py).
'use strict';
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const R = require('../../src/atlas/web/map/region.js');

const golden = JSON.parse(fs.readFileSync(path.join(__dirname, 'regions_golden.json'), 'utf8'));
const catalog = JSON.parse(fs.readFileSync(path.join(__dirname, 'regions_catalog.json'), 'utf8'));

for (const g of golden) {
  test('closest city: ' + g.label, () => {
    const c = R.closest(catalog, g.lat, g.lon);
    assert.equal(c ? c.id : null, g.expected);
  });
}
